<script setup lang="ts">
import type { ReconciledReceiptEffect, ReceiptReconciliation, ReconciliationValueTrace } from '~/types/reconciliation'
import { displayDecimal } from '~/utils/catalog'
import { receiptSourceLabels, shareText } from '~/utils/receipt'
const props = defineProps<{ effect: ReconciledReceiptEffect; saved?: ReceiptReconciliation }>()
const traceNames = { inflow: '입고', observation: '확인한 수량', production: '생산', waste: '폐기 · 직원식' }
function traceLink(row: ReconciliationValueTrace) { return row.kind === 'inflow' ? `/receipts/${row.event_id}` : row.kind === 'production' ? `/productions/${row.event_id}` : row.kind === 'waste' ? `/wastes/${row.event_id}` : null }
function materialName(id: string) { return props.effect.materials.find(item => item.material_id === id)?.material_name ?? id }
</script>
<template>
  <div class="receipt-reconciliation-result">
    <section aria-label="실제 구입과 수량 반영"><h3>실제 구입과 수량 반영</h3><dl class="reconciliation-fields"><div><dt>실제 입고</dt><dd class="preview-result">{{ displayDecimal(effect.input_quantity) }}{{ effect.input_unit }} · {{ displayDecimal(effect.amount) }}원</dd></div><div><dt>실제 입고일</dt><dd>{{ effect.receipt_date }}</dd></div><div><dt>실사에 포함된 수량</dt><dd>{{ displayDecimal(effect.included_quantity) }}{{ effect.unit }}</dd></div><div><dt>현재 새로 더할 수량</dt><dd>{{ displayDecimal(effect.unreflected_quantity) }}{{ effect.unit }}</dd></div></dl><p class="field-hint">확인한 포함 수량은 다시 더하지 않습니다. 마지막 확인 수량과 확인 시각도 그대로 유지합니다.</p></section>
    <section aria-label="구입금액과 기존 가치 비교"><h3>구입금액과 기존 가치 비교</h3><dl class="reconciliation-fields"><div><dt>포함분 실제 금액</dt><dd>{{ displayDecimal(effect.included_amount) }}원</dd></div><div><dt>새 유입 금액</dt><dd>{{ displayDecimal(effect.unreflected_amount) }}원</dd></div><div><dt>이미 반영한 가치</dt><dd>{{ displayDecimal(effect.booked_value) }}원</dd></div><div><dt>포함분 가치 차액</dt><dd>{{ displayDecimal(effect.value_difference) }}원</dd></div></dl><p class="field-hint">이미 반영한 가치는 선택한 실사 당시 근거입니다. 현재 평균으로 바꾸지 않습니다. 음수 차액은 가치를 줄이는 보정입니다.</p></section>
    <section aria-label="현재 품목별 가치 변화"><h3>현재 품목별 가치 변화</h3><p v-if="!effect.materials.length" class="notice">현재 보유 수량과 가치를 바꾸는 효과가 없습니다.</p><section v-for="item in effect.materials" :key="item.material_id" class="reconciliation-material"><h4><NuxtLink :to="`/materials/${item.material_id}`">{{ item.material_name }}</NuxtLink></h4><dl class="reconciliation-fields"><div><dt>이전 정산 기준</dt><dd>{{ item.before ? `${displayDecimal(item.before.quantity)}${item.unit} · ${item.before.value === null ? '가치 미확인' : displayDecimal(item.before.value) + '원'}` : '아직 정산 기준 없음' }}</dd></div><div><dt>반영 후 정산 기준</dt><dd>{{ displayDecimal(item.after.quantity) }}{{ item.unit }} · {{ item.after.value === null ? '가치 미확인' : `${displayDecimal(item.after.value)}원` }}</dd></div><div><dt>기존 보유 가치 보정</dt><dd>{{ displayDecimal(item.value_delta) }}원</dd></div><div><dt>새로 더하는 수량·금액</dt><dd>{{ displayDecimal(item.inflow_quantity) }}{{ item.unit }} · {{ displayDecimal(item.inflow_value) }}원</dd></div><div><dt>마지막 확인 수량</dt><dd>{{ item.observation ? displayDecimal(item.observation.quantity) + item.unit : '아직 확인한 수량 없음' }}</dd></div></dl></section></section>
    <section aria-label="이미 사용된 부분의 별도 보정"><h3>이미 사용된 부분의 별도 보정</h3><p class="preview-result">{{ displayDecimal(effect.separate_adjustment) }}원</p><p class="field-hint">이미 소모되거나 전량 폐기된 부분은 별도 금액으로 보관합니다. 이전 판매 원가·실사 소모·배분 기록은 그대로 유지합니다. 이 금액은 이번 보정만 나타냅니다.</p></section>
    <section v-if="effect.selections.length" aria-label="선택한 실사 근거"><h3>선택한 실사 근거</h3><section v-for="selection in effect.selections" :key="selection.position" class="reconciliation-selection"><h4><NuxtLink :to="`/stocktakes/${selection.stocktake_id}`">포함 근거 {{ selection.position + 1 }}의 실사</NuxtLink></h4><p>{{ displayDecimal(selection.included_quantity) }}{{ selection.unit }} · {{ selection.source.kind === 'all_available' ? '남은 근거 전체에서 확인' : receiptSourceLabels[selection.source.source_key.kind] }}</p><dl class="reconciliation-fields"><div><dt>당시 반영 가치</dt><dd>{{ displayDecimal(selection.booked_value) }}원</dd></div><div><dt>실제 포함 금액</dt><dd>{{ displayDecimal(selection.actual_included_value) }}원</dd></div><div><dt>차액</dt><dd>{{ displayDecimal(selection.value_difference) }}원</dd></div></dl><details><summary>연결한 세부 근거 {{ selection.portions.length }}개</summary><ul class="history-list"><li v-for="portion in selection.portions" :key="portion.position"><p>{{ receiptSourceLabels[portion.source_key.kind] }} · 실사 포함 몫 {{ shareText(portion.included_share) }}</p><p>원래 근거 연결 몫 {{ shareText(portion.reserved_source_share) }}</p><p>당시 가치 {{ displayDecimal(portion.booked_value) }}원 · 실제 포함 금액 {{ displayDecimal(portion.actual_included_value) }}원</p><p class="material-id">원래 근거 {{ portion.source_key.id }} · 당시 버전 {{ portion.source_version_id }}</p></li></ul></details></section></section>
    <details v-if="effect.trace.length" class="reconciliation-trace"><summary>후속 기록의 계산용 비교 {{ effect.trace.length }}건</summary><p class="field-hint">기존 확정 기록을 수정한 결과가 아닙니다. 이전 유효 보정까지 반영한 계산과 이번 보정을 더한 계산을 비교합니다.</p><ul class="history-list"><li v-for="(row, index) in effect.trace" :key="`${row.event_id}-${row.material_id}-${index}`"><NuxtLink v-if="traceLink(row)" :to="traceLink(row)!">{{ traceNames[row.kind] }} 원기록 보기</NuxtLink><p v-else>확인 수량의 당시 버전 <span class="material-id">{{ row.event_id }}</span></p><p>{{ materialName(row.material_id) }} · 기록 {{ row.seq }}</p><dl class="reconciliation-fields"><div><dt>이전 보정까지 계산</dt><dd>{{ displayDecimal(row.base_value_before) }} → {{ displayDecimal(row.base_value_after) }}원</dd></div><div><dt>이번 보정 포함 계산</dt><dd>{{ displayDecimal(row.proposed_value_before) }} → {{ displayDecimal(row.proposed_value_after) }}원</dd></div><div><dt>사용된 가치 비교</dt><dd>{{ displayDecimal(row.base_closed_value) }} → {{ displayDecimal(row.proposed_closed_value) }}원</dd></div></dl></li></ul></details>
    <section v-if="effect.order_after" aria-label="실제 입고로 완료하는 주문"><h3>실제 입고로 완료하는 주문</h3><p>확정 주문량 {{ displayDecimal(effect.order_after.ordered_quantity) }}{{ effect.order_after.unit }} · 실제 입고 {{ displayDecimal(effect.order_after.received_quantity) }}{{ effect.order_after.unit }} · 차이 {{ displayDecimal(effect.order_after.difference) }}{{ effect.order_after.unit }}</p><p class="field-hint">주문 완료는 실사 포함 여부와 관계없이 실제 입고량을 기준으로 합니다.</p><NuxtLink :to="`/orders/${effect.order_after.order_id}`">주문과 이력 보기</NuxtLink></section>
    <details v-if="saved" class="holding-references"><summary>확정 보정의 연결 기록</summary><p class="material-id">보정 {{ saved.id }}</p><p v-if="!saved.material_results.length">현재 보유 수량·가치가 달라지지 않아 새 정산 근거를 만들지 않았습니다.</p><ul class="history-list"><li v-for="item in saved.material_results" :key="item.effect_id"><p>{{ materialName(item.material_id) }}</p><p class="material-id">효과 {{ item.effect_id }} · 정산 근거 {{ item.holding_version_id }}</p></li><li v-for="item in saved.selection_results" :key="item.reservation_id"><p>포함 근거 {{ item.selection_position + 1 }} · 세부 근거 {{ item.portion_position + 1 }}</p><p class="material-id">연결 {{ item.link_id }} · 연결 버전 {{ item.link_version_id }} · 예약 {{ item.reservation_id }}</p></li></ul></details>
  </div>
</template>
